/bin/bash -lc "find / -type f \\( -name pvpython -o -name paraview -o -name vtkpython -o -name 'TTK*' \\) 2>/dev/null | sed -n '1,120p'; find / -iname '*ttk*' -type f 2>/dev/null | sed -n '1,100p'; python - <<'PY'
try:
 import vtk
 print('vtk', vtk.vtkVersion.GetVTKVersion())
except Exception as e: print('no vtk',e)
try:
 import paraview
 print('paraview present')
except Exception as e: print('no pv',e)
PY"

